"""Citable methods metadata over frozen reviewed serving releases."""
import json,pathlib
class Methods:
 def __init__(self,snapshot):self.snapshot=json.loads(pathlib.Path(snapshot).read_text())
 def describe(self,kind,query):
  if kind=='clinical':
   meta=self.snapshot['SUS_CLINICAL_DATA']['clinical-metadata.json'];family=query['family'];year=query['year']
   if family not in meta.get('approved_scopes',{}).get(str(year),[]):raise ValueError('Unavailable reviewed scope')
   sim=family=='DO';preview=meta.get('preview_scopes',{}).get(str(year)) if sim else None
   unit='Death-certificate records in SIM,not SUS-only' if sim else 'RD inpatient administrative records,not deduplicated admissions or people' if family=='RD' else 'PA individual ambulatory billing source records,not quantities or people;consolidated BPA excluded' if family=='PA' else 'AM medication authorization/billing source records,not prescriptions,dispensed units or people'
   period=('Death year;'+(preview['status'] if preview else 'stable release')) if sim else ('Processing-file year;Jan-Jul partial' if year==2026 else 'Processing-file year,not necessarily attendance year')
   fields={'RD':'DIAG_PRINC','PA':'PA_CIDPRI','AM':'AP_CIDPRI','DO':'CAUSABAS'}
   return {'release_id':meta['release_id'],'artifact_sha256':meta['clinical_sha256'],'query_spec':query,'unit':unit,'time_basis':period,'diagnosis_field':fields[family],'geography':'Residence municipality;frozen2024catalog;DF excluded,unknown/invalid residence excluded','grain':'family x year x residence municipality x exact source CID string','codes':'CID detail preserved;bare3-character codes are not recoded as a4-character subcategory;prefix queries list cells,not category totals','suppression':'Under20source-record cells absent;remaining fixed10-wide intervals;targeted whole-UF/CID withholding retained;absence unknown,not zero','preview_vintage':preview,'warnings':meta['warnings']+(preview['warnings'] if preview else []),'methods_paragraph':f'We described {unit}. The time basis was {period}. We used frozen release {meta["release_id"]}, SHA256 {meta["clinical_sha256"]}, filtered using the accompanying query specification. Results retain the existing municipal CID lattice and disclosure rules: cells below 20 source records are absent and visible cells are fixed 10-wide intervals, with additional targeted withholding and DF exclusion. Missing rows were not interpreted as zero. We did not estimate unique people, prevalence, clinical comorbidity or causal effects. Publisher reconciliation and source-completeness limitations are supplied with the export.'}
  if kind=='capacity':
   from sus_health_mcp.period_gates import require_period
   meta=self.snapshot['SUS_STAGED_DATA']['metadata.json'];require_period(meta,query['family'],query['year'],query['month'],query['uf'])
   return {'release_id':meta['release_id'],'artifact_sha256':meta['capacity_sha256'],'query_spec':query,'time_basis':'Frozen monthly CNES registry snapshot;2026Jan-Aug only','unit':'LT registered beds by source bed type;ST/SR/HB registry rows,not beds or patients','geography':'Facility registry municipality,not residence or catchment','warnings':meta['registry_warnings'],'verified_periods':[r for r in meta['publisher_periods'] if r['family']==query['family'] and r['year']==query['year'] and r['month']==query['month']],'methods_paragraph':f'We retrieved fixed monthly CNES registry cells from release {meta["release_id"]}, SHA256 {meta["capacity_sha256"]},with the accompanying query specification. Registered beds or services were not interpreted as real-time occupancy, staffing, appointments or clinical activity. Publisher period gates were retained, and unavailable source periods were not treated as zero.'}
  env='SUS_KNOWN_CARE_DATA' if kind=='known_care' else 'SUS_DEEPER_DATA' if kind=='deeper' else None
  if not env:raise ValueError('Unknown output kind')
  m=self.snapshot[env]['known-care-metadata.json' if kind=='known_care' else 'metadata.json']
  return {'release_id':m['release_id'],'artifact_sha256':m['known_care_sha256' if kind=='known_care' else 'artifact_sha256'],'query_spec':query,'time_basis':'Processing-file year;2026Jan-Jul partial','unit':'PA billing source records,not people or quantities','geography':'Residence municipality;known-care flow endpoint is billing-provider municipality,not confirmed clinical hospital','warnings':m['warnings'],'surface_definitions':m.get('surfaces'),'methods_paragraph':'We retrieved the existing frozen billing intervals identified by the release and SHA256 in this manifest,with no new combinations, totals or derived rates. Records are billing events, not unique people or evidence of a clinical subtype, treatment eligibility, unmet need or screening. Existing targeted withholding, DF exclusion and missing-as-unknown rules were retained.'}
